script:
(function () {
  'use strict';
  // Repossession of personal property sold on the installment method, following IRS Pub. 537 (2025),
  // "Personal Property" and Worksheet C.
  //   Line 1 = FMV of the repossessed property (plus the value of anything else received from the buyer).
  //   Line 4 = unpaid balance x gross profit % (unrealized profit); line 5 = unpaid balance - line 4
  //   (basis in the obligation); line 7 = line 5 + repossession costs; line 8 = line 1 - line 7 = gain
  //   (or loss), same character as the gain on the original sale. Basis in the property = its FMV.
  //   Optional gross profit % from the sale: gross profit = selling price - adjusted basis - selling
  //   expenses; contract price = selling price - mortgage assumed + any excess of that mortgage over
  //   basis plus expenses; percentage = gross profit / contract price.
  // Verified (Node, scratchpad lkrepo/tests/repo.test.js) against Pub. 537's piano example: FMV $1,400,
  //   unpaid $800, gross profit 40%, costs $75 -> unrealized profit $320, obligation basis $480,
  //   line 7 $555, gain $845. Pub. 537 land sale ($25,000, basis $19,000, expenses $1,000) -> 20%.
  //   Loss case: FMV $300 -> loss $255. Blank or negative input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pctFmt = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }

  function grossProfit(price, basis, exp, assumed) {
    var gp = price - basis - exp;
    var cp = price - assumed + Math.max(0, assumed - basis - exp);
    return { gp: gp, cp: cp, pct: gp > 0 && cp > 0 ? Math.min(1, gp / cp) : 0 };
  }

  function worksheetC(fmv, other, unpaid, pct, costs) {
    var l1 = fmv + other, l4 = unpaid * pct, l5 = unpaid - l4, l7 = l5 + costs;
    return { l1: l1, l2: unpaid, l3: pct, l4: l4, l5: l5, l6: costs, l7: l7, l8: l1 - l7 };
  }

  var IDS = ['rpiResult', 'rpiObligBasis', 'rpiNewBasis', 'rpiUnrealized', 'rpiNote', 'rpiGpShow'];

  function update() {
    var mode = el('rpiGpMode').value;
    el('rpiGpEnterWrap').hidden = mode !== 'enter';
    el('rpiGpFigureWrap').hidden = mode !== 'figure';
    var fmv = read('rpiFmv'), unpaid = read('rpiUnpaid'), costs = read('rpiCosts', true), other = read('rpiOther', true);
    var err = el('rpiError'), msg = '', pct = NaN, g = null;
    if (mode === 'figure') {
      var price = read('rpiSalePrice'), basis = read('rpiSaleBasis'), exp = read('rpiSaleExp', true), assumed = read('rpiSaleDebt', true);
      if (isNaN(price) || price <= 0) msg = 'Enter the selling price of the original sale.';
      else if (isNaN(basis) || basis < 0) msg = 'Enter your adjusted basis in the property when you sold it ($0 or more).';
      else if (isNaN(exp) || exp < 0 || isNaN(assumed) || assumed < 0) msg = 'Selling expenses and the assumed debt cannot be negative.';
      else if (assumed > price) msg = 'The debt the buyer took over cannot be more than the selling price.';
      else {
        g = grossProfit(price, basis, exp, assumed);
        if (g.gp <= 0) msg = 'The original sale had no gross profit, so it could not be reported on the installment method.';
        else pct = g.pct;
      }
    } else {
      var p = read('rpiGp');
      if (isNaN(p) || p <= 0 || p > 100) msg = 'Enter a gross profit percentage above 0% and up to 100%.';
      else pct = p / 100;
    }
    if (!msg) {
      if (isNaN(fmv) || fmv < 0) msg = 'Enter the fair market value of the property you took back ($0 or more).';
      else if (isNaN(unpaid) || unpaid < 0) msg = 'Enter the unpaid balance of the buyer’s note ($0 or more).';
      else if (isNaN(costs) || costs < 0 || isNaN(other) || other < 0) msg = 'Repossession costs and other amounts received cannot be negative.';
      else if ([fmv, unpaid, costs, other].some(function (v) { return v > 1e12; })) msg = 'Amounts are too large.';
    }
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); setText('rpiResultLabel', 'Gain or loss on the repossession'); el('rpiLines').innerHTML = ''; return; }

    var w = worksheetC(fmv, other, unpaid, pct, costs);
    setText('rpiResultLabel', w.l8 < 0 ? 'Loss on the repossession' : 'Gain on the repossession');
    setText('rpiResult', money.format(Math.abs(w.l8)));
    setText('rpiObligBasis', money.format(w.l5));
    setText('rpiUnrealized', money.format(w.l4));
    setText('rpiNewBasis', money.format(fmv));
    setText('rpiGpShow', g ? pctFmt.format(pct) + ' (' + money.format(g.gp) + ' gross profit ÷ ' + money.format(g.cp) + ' contract price)' : pctFmt.format(pct));

    var kind = el('rpiChar').value === 'ordinary' ? 'ordinary income' : 'capital gain';
    var note;
    if (w.l8 > 0) note = 'You have a gain of ' + money.format(w.l8) + '. It is ' + kind + ', the same character as the gain on the original sale, and goes on the form you used to report that sale (for example Form 4797 or Form 6252).';
    else if (w.l8 < 0) note = 'You have a loss of ' + money.format(-w.l8) + '. It has the same character as the original gain (' + kind.replace('gain', 'loss').replace('income', 'loss') + ').';
    else note = 'The property is worth exactly your basis in the note plus your repossession costs, so there is no gain or loss.';
    note += ' Your basis in the property you took back is its fair market value, ' + money.format(fmv) + '.';
    setText('rpiNote', note);

    var lines = [
      ['1', other > 0 ? 'Fair market value of the property plus other value received' : 'Fair market value of the repossessed property', money.format(w.l1)],
      ['2', 'Unpaid balance of the installment obligation', money.format(w.l2)],
      ['3', 'Gross profit percentage', pctFmt.format(w.l3)],
      ['4', 'Unrealized profit (line 2 times line 3)', money.format(w.l4)],
      ['5', 'Basis of the obligation (line 2 minus line 4)', money.format(w.l5)],
      ['6', 'Repossession costs', money.format(w.l6)],
      ['7', 'Line 5 plus line 6', money.format(w.l7)],
      ['8', 'Gain or (loss) on the repossession', signed(w.l8)]
    ];
    el('rpiLines').innerHTML = lines.map(function (l) {
      return '<tr><td>' + l[0] + '</td><td>' + l[1] + '</td><td>' + l[2] + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rpiForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
